        public static CDBoxPageDefinition Create(ICDBoxLogger logger,
            ICDBoxPageService pages)
        {
            var router = new LayerManagerPageRouter(logger, pages);
            return new CDBoxPageDefinition(PageId, "图层管理器",
                BuildDocument, router.Route)
            {
                Width = 1480,
                Height = 900,
                MinimumWidth = 720,
                MinimumHeight = 620
            };
        }

        public static string BuildDocument()
        {
            var html = new StringBuilder();
            html.Append("<!doctype html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>图层管理器</title><style>");
            html.Append(BuildStandaloneVariables());
            html.Append(BuildStyles(true));
            html.Append("</style></head><body><div id=\"layerManagerPage\" style=\"height:100%\"></div><div id=\"studioToastHost\" class=\"toast-host\"></div><script>");
            html.Append("function post(n,a){try{chrome.webview.postMessage('studio|'+n+'|'+encodeURIComponent(a||''));}catch(ex){}}function toast(m,k){var h=document.getElementById('studioToastHost'),e=document.createElement('div');e.className='toast '+(k||'info');e.textContent=m;h.appendChild(e);setTimeout(function(){e.classList.add('show');},10);setTimeout(function(){e.classList.remove('show');setTimeout(function(){e.remove();},180);},3200);}window.CDBoxStudioToast=toast;");
            html.Append(BuildComponentScript());
            html.Append("var layerManagerEditor=window.CDBoxLayerManagerPage.create({rootId:'layerManagerPage',post:post,toast:toast,standalone:true});window.addEventListener('error',function(e){post('layerManagerPageError',(e.message||'页面异常')+'\\n'+(e.error&&e.error.stack||''));});setTimeout(function(){post('ready','');},50);");
            html.Append("</script></body></html>");
            return UtilityWorkbench.Apply(html.ToString());
        }

        private static string BuildStandaloneVariables()
        {
            return @":root{--bg:#f5f7fb;--panel:#fff;--panel2:#f8fafc;--muted:#64748b;--text:#162033;--line:#dce8f6;--brand:#3b82f6;--brand2:#7c3aed;--chip:#f1f5f9;--chipText:#475569;--shadow:0 20px 45px rgba(30,41,59,.08);--shadow2:0 10px 24px rgba(30,41,59,.08)}body[data-theme='fresh']{--bg:#f3f7ff;--panel:#fff;--panel2:#eef4ff;--muted:#65758f;--text:#172033;--line:#dbe7ff;--brand:#2563eb;--brand2:#9333ea;--chip:#eef2ff;--chipText:#3730a3}body[data-theme='dark']{--bg:#0f172a;--panel:#172033;--panel2:#111827;--muted:#94a3b8;--text:#e5e7eb;--line:#26364d;--brand:#60a5fa;--brand2:#a78bfa;--chip:#1e293b;--chipText:#cbd5e1;--shadow:0 20px 45px rgba(0,0,0,.28);--shadow2:0 10px 24px rgba(0,0,0,.24)}*{box-sizing:border-box}html,body{height:100%;margin:0;background:var(--bg);color:var(--text);font-family:'Microsoft YaHei UI','Segoe UI',sans-serif;overflow:hidden}.toast-host{position:fixed;right:20px;bottom:20px;display:grid;gap:8px;z-index:999}.toast{opacity:0;transform:translateY(8px);background:#172033;color:#fff;border-radius:11px;padding:10px 13px;box-shadow:0 12px 30px rgba(15,23,42,.22);transition:.18s}.toast.show{opacity:1;transform:none}.toast.success{background:#047857}.toast.warning{background:#b45309}.toast.error{background:#b91c1c}";
        }

        private static string Html(string value)
        {
            if (string.IsNullOrEmpty(value)) return string.Empty;
            return value.Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;").Replace("\"", "&quot;").Replace("'", "&#39;");
        }

        private static string HtmlAttr(string value)
        {
            return Html(value).Replace("\r", string.Empty).Replace("\n", " ");
        }
    }
}
